INSERT INTO company (id, owner_user_id, company_name, description, company_scale, financing_stage, industry, website, logo_url, benefits, status, created_at, updated_at, company_created_at, registered_capital, audit_status, audited_at) VALUES
(400001, 200001, '东莞市恒亚罗斯计算机科技有限公司', '东莞市恒亚罗斯计算机科技有限：南极芯科技是一家专业设计，研发，生产，销售数字化工厂富有创新能力的软件企业，在软件应用系统规划和智能MES智能工厂信息化服装ERP供应链系统WMS IOT PLM工业互联网平台智能工厂规划具有丰富经验的专家顾问所创办；企业研发团队全部是计算机软件相关专业本科以上学历，平均年龄不到30岁，是一个优秀、经验丰富和极具创造力的年轻团队。公司依托于与各大院校大学的密切合作，有效利用人才与资源优势，实现产学研一体化运作，一方面提升企业形象和扩大业务渠道，一方面借助于科研联合和政府扶植推动产品技术和业务发展、等的密切联系和以往业务关系，逐渐建立起实质性的业务合作，并形成新的业务模式。目前软件著作权及专利几十项、主要业务、服装ERP MES智能制造 IOT物联网，供应链系统WMS IOT PLM WMS立库工业互联网平台产品、研发投入产生的经济和社会效益。提高生产效率，南极芯工业互联网云平台可以对生产过程进行实时监测和数据分析，帮助企业了解生产情况，提高生产效率。通过实时监测和数据分析，企业可以及时发现问题，进行调整和优化，避免生产中出现的问题和故障，减少停机时间和损失，提高生产效率。降低生产成本，南极芯工业互联网云平台可以通过对生产过程进行优化，降低生产成本。通过对生产过程的监测和分析，企业可以发现生产中的浪费和瓶颈，进行优化和调整，降低生南极芯工业互联网云平台可以促进产业升级，推动企业从传统制造向智能制造转型。通过工业互联网云平台，企业可以实现数字化、网络化和智能化的生产模式，提高生产效率和产品质量，降低生产成本，提高企业的竞争力和盈利能力，促进产业升级。南极芯服装供应链ERP，南极芯MES智能智造管理系统，南极芯WMS智慧立库系统，南极芯IoT物联网，人工智能机器人。全力协同产业智能制造数字化智能化标杆工厂，数字化智能化全面转型升级，全力推动科技与产业融合发展。', 2, 1, '计算机软件', 'https://www.zhaopin.com/jobdetail/CC668565120J40736166805.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400002, 200002, '广东南方数码科技股份有限公司', '广东南方数码科技股份有限公司成立于2003年，总部位于广州，是一家集数据、软件、服务于一体的中国领先的地理信息产业服务商、中国地理信息产业“百强企业”，产品业务覆盖地理信息产业链，提供一站式的就近服务。公司是信息产业部认定的“软件企业”，同时也是广东省认定的“高新技术企业”、“广州市重点软件企业”、“广东省优秀自主品牌”，具有测绘甲级资质、CMMI3级认证、系统集成三级资质、ISO9001：2008国际质量体系认证。公司全面面向数字城市，以数据为基础，以基础测绘、房产、国土、市政、规划等行业为核心发展地理信息产业，产品服务贯穿产业链。公司拥有遍布全国的数码专业分公司，专业、专注、就近服务。目前，公司已有数百个政务管理系统稳定运行在各级政府和行业管理部门。公司承担了多项省、市、区科技攻关项目，并多次获国家、省、市政府和科技部门的奖励。自主开发的70多个软件产品获得“软件产品登记”和“著作权登记”。其中南方地形地籍成图与建库软件（ CASS）拥有全国90%的市场份额，并成为业界事实标准；房测之友BMF成为房地产测绘行业唯一通过权威机构评测的专业软件，居同类软件市场占有率之首；CMS成为国土资源部推荐使用的城镇建库软件。秉承“以人为本、专业专注、和谐共赢”的理念，南方数码始终坚持以“数据·软件•服务”为核心，以提升地理信息价值为已任，愿与同行一起，推动中国的信息化建设事业，让更多人体验地理信息价值！', 4, 0, '计算机软件', 'https://www.zhaopin.com/jobdetail/CC133964100J40788029412.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400003, 200003, '河南二建集团', '河南省第二建设集团有限公司创立于1954年，是一家集建筑、安装、装饰装修、市政、房地产开发等为一体的大型现代企业。现拥有房屋建筑工程施工总承包特级资质，市政公用工程施工、机电设备安装工程施工总承包壹级资质，建筑行业（建筑工程、人防工程）甲级设计资质，、钢结构工程、建筑装饰装修工程、高耸构筑物工程、特种工程、环保工程专业承包壹级资质，建筑幕墙、装饰装修、消防设计与施工一体化壹级资质，集团公司注册资本金三亿陆百三十七万元人民币，资信等级AA*。现有职工2600余人，年施工生产能力在100亿元以上。公司市场遍布国内 26个省、市，并已走向国际工程承包市场，先后开拓10个国家和地区，目前主要在土耳其、阿尔及利亚和尼日利亚。集团公司先后组建并获批了河南省企业技术中心、河南省清水混凝土工程技术研究中心、河南省博士后研发基地和院士工作站，并创导了“以实养研”的技术创新模式，保证科研成果的及时实施和应用。集团公司已建立科学、规范、严格的管理体系，施工工艺、技术创新应用、质量管理、安全文明施工等社会化服务全部实现标准化管理。通过科学的管理制度和严谨的流程管控，协同办公、人力资源、资金、财务、经营、档案、邮件、网站及综合项目管理九大系统的信息化，实现全面现代化企业常态化管理。集团公司凭借良好的信誉和雄厚的经济、人才、技术实力，承建了大批大中型工程项目，建设项目涉足能源（火电）、核电、房屋建筑、输变电、教育、电信、移动通信、金融银行、造纸、建材（水泥）、煤化工、电解铝、冶炼、化工、市政公用设施等领域的基本建设。河南二建集团以“服务社会、壮大企业、回报股东、造福员工”为宗旨，以“打造百年名企，追求和谐共生”为企业愿景，凭质量拓展市场，靠诚信赢得客户。开放、求实、创新、奋进的河南二建集团愿与社会各界精诚合作，携手并进，共创美好未来！', 5, 0, '建筑设备安装', 'https://www.zhaopin.com/jobdetail/CC289314820J40747209302.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400004, 200004, '香港中文大学深圳研究院', '2007年5月，在深圳市的支持下，香港中文大学在深圳设立香港中文大学深圳研究院（简称“深研院”）。深研院主体大楼坐落于深圳虚拟大学园国家大学科技园内，于2011年11月落成并投入使用。大楼建筑面积约2.5万平方米，地上建筑9层，设有大型演讲厅、培训课室、科研实验区及培育中小企业工作区等不同的应用区域，为科学研究，人才培训、产业合作及技术转移等提供场地和设施。学研提升结合国家科技发展规划与深圳市科技发展需求，深研院重点推动生物医药、信息科技及可持续发展等领域的科研发展。目前，香港中文大学深圳研究院已建立3个国家重点实验室的深圳基地，包括消化疾病研究国家重点实验室深圳研究基地、农业生物技术国家重点实验室深圳基地、再生医学教育部重点实验室深圳基地，另有4个深圳市重点实验室及3个深圳市工程实验室。经过数年悉心发展，深研院的科研实力获得了国家的认可，作为国家、省市项目的依托单位，已承担各级科研项目500余项。此外，深研院积极推动产学研合作，重视横向项目的合作与发展，利用优秀的研究平台和研究资源，吸引科研项目落地，并通过与外部机构合作，在促进科研产业化的同时进一步提升科研水平。人才培育深研院依托中大的优势师资资源和深厚的教学、科研基础，结合深圳市乃至全国范围内对高层次、专业化、国际化人才的需求；延续中大中英兼重、多重文化的教育传统，策划并开展各类面向全社会、适合本地经济社会发展的培训工作，旨在为深圳、粤港澳大湾区乃至全国培养优秀人才，为业界在相关领域的技术进步提供良好的技术与理论支持。深研院积极配合与落实深圳市政府有关高层次人才就业的系列政策，推动博士后入站、高层次人才认定等相关工作。此外，深研院不定期开展国际学术研讨会及讲座，在提升人才专业技能的同时促进不同行业间专业人士的沟通、交流，为培育高端人才搭建高层次的平台。全球接轨深圳作为大湾区中最具创新活力的城市之一，深研院通过举办国际性的论坛、研讨会、工作坊等，吸引全球各地来自不同领域的人才聚首深圳，为学术研讨提供国际性视野和平台，推动国际高端技术成果、项目的落地。截至2023年12月，深研院已经成功举办深圳·联合国气候峰会COP28新机遇大会、粤港澳大湾区发展论坛、中以合作创新论坛、3D打印与再生医学国际论坛暨工作坊等国际性的学术活动。吸引了来自中国大陆、港澳台、德国、以色列、英国、美国等不同国家或地区的学者的积极响应和参与。创新发展深研院立足地方产业发展的技术优势，不断激发科技活力和推动技术成果高效转化；坚持“技术创新，开放共享”的理念，持续加强与社会各界的合作创新。此外，深研院通过引进大学系统、健全的知识产权和技术转移管理体系，在为横纵发展和科研团队管理提供完备服务与指引的同时，积极探索科研机构、科研项目管理和技术转移的新模式。深研院于2018年成立众创中心，中心立足于本地，进行初创公司的培育孵化，旨在形成创业生态系统，促进深港两地产学研深入合作，以带动新一代信息技术、生物科学、智能制造等战略性产业的创新和发展。', 3, 0, '政府/公共事业', 'https://www.zhaopin.com/jobdetail/CC224678420J40426432406.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400005, 200005, '成都新朝阳作物科学股份有限公司', '新朝阳股份公司系一家专注于绿色农业的生物科技公司，是行业领先的植物源生物农药科技企业，也是绿色农业的倡导者和先行者。公司自1999年设立以来，始终以“敬畏自然、尊重生命、健康农业”为公司核心价值观，始终以“科技创新驱动农业绿色发展”为使命，始终以“保障农产品质量安全、提升农业产业价值和改善农业生态环境”为企业发展目标。公司致力于绿色农业生物技术创新，聚焦农业土壤全程健康管理、作物病虫草害绿色防控、作物生长和营养健康、农产品品质与产量提升，以生物技术为引擎，为农业生产提供从土壤到餐桌的全程绿色植物保护技术，助推现代农业发展。公司是高新技术企业，也是工信部认定的首批国家级专精特新“小巨人”企业。公司以自主研发的天然植物源提取物结合生物工程技术为核心，围绕农作物整个生长周期进行技术研发，形成了多项独创核心技术，截止2020年7月，公司获得了境内外78项发明专利和26项有机绿色农业投入品认证。根据中国农药信息网的数据，公司是我国农业农村部生物农药登记作物及防治对象最丰富、产品系统性最全面的企业之一。公司设立有生物技术研究院，截至2020年3月31日，拥有专职研发人员54人，其中博士、硕士23人，具有中高级职称的人员16名。生物技术研究院设置了“生物调控技术”、“生物防控农药”、“土壤修护与营养技术”三个创制中心和“作物免疫基因编辑技术实验室”，构建了以段留生、徐明岗、国锦琳、李建中4名专家作为首席科学家进行指导的研发体系。公司还携手国内高校和行业科研机构，设立了院士（专家）创新工作站、四川省博士后创新实践基地和成都市产学研联合实验室，长期为公司的持续创新提供技术支持。公司的各类研发项目曾获得多项重要奖项，其中“我国典型红壤区农田酸化特征及防治关键技术构建与应用”获得国家科学技术进步奖二等奖；“我国典型区域农田酸化特征及防治技术与应用”项目获得神农中华农业科技奖一等奖及中国农科院科学技术成果奖；“芸苔素质量控制关键技术创建与应用”项目获得神农中华农业科技奖二等奖。公司注重科技创新的成果转化，产品覆盖农作物整个生长周期，主要产品具有高效、安全、环境友好的特性。公司的产品主要包括生物农药（植物生长调节剂、病虫草害绿色防控农药）、植物源生物刺激剂综合营养类产品及土壤调理剂。', 4, 0, '农/林/牧/渔', 'https://www.zhaopin.com/jobdetail/CC443150410J40692600114.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400006, 200006, '昆山华海环保科技有限公司', '冬日暖阳，不及你在身旁，相约12月，愿招聘的愿望实现~昆山华海环保科技有限公司位于沪苏杭核心区域——昆山经济技术开发区（国家级开发区），生产基地（江苏华海三联净化材料有限公司）在江苏省泰州市顾高工业园区，华海是以科、工、贸为一体的综合型企业。公司自主开发研制催化剂、净化剂和吸附剂产品。公司传承原化工部下属核心研究所的技术，公司产品主要应用于石油炼制、天然气化工、煤化工、冶炼厂等行业和装置的各种原料气（油），以及各种尾气和污水净化等环保领域。公司致力于专业的催化剂研制、开发、生产和销售。公司技术研发力量雄厚，由享受国务院津贴的行业专家带领一批高精尖技术人才进行科研攻关。多年来，公司自主开发研制的催化剂、净化剂和吸附剂产品三十余种。公司产品先后通过省部级及国家级技术认定，大部分可取代进口，产品技术起点高，应用范围广，部分产品填补了国内催化剂市场的空白。公司先后荣获江苏省科技型中小企业、江苏省高新技术企业、国家技术科技进步奖、江苏省科技进步奖、国家级新产品奖等十余项嘉奖。公司秉承科技环保创新，客户遍及全国，出口印尼、美国、日本等十几个国家。公司坚持技术为先导，服务伴始终的原则，同国内大型著名设计院保持紧密的技术协作关系，能根据客户的具体工艺条件和装置特点进行量身定制产品。本公司以一流的产品质量、良好的服务声誉、雄厚的技术力量、广泛的合作关系得到客户的信赖。公司愿为地球环保尽一份绵薄之力，愿与客户及供应商共同实现互惠互利。', 2, 0, '石油/石化', 'https://www.zhaopin.com/jobdetail/CC464266120J40211037810.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400007, 200007, '唐山松下产业机器有限公司', '唐山松下产业机器有限公司（简称PWST）成立于1994年8月，是由日本松下集团和唐山开元电器有限公司共同投资兴建的中日合资企业。日本松下的投资比例为60%，唐山开元电器有限公司的投资比例为40%。公司采用日本松下先进的管理和技术，使用世界一流的制造、调试及检测设备，生产商标为"Panasonic"的各种CO2/MAG/MIG气体保护焊机、交／直流氩弧焊机、交直流弧焊机、等离子切割机、电阻焊机、焊接机器人及相关产品，其中产品的10%出口。唐山松下在全国各主要大中城市都设有代理店和销售店，拥有完善的产品销售、部品供应和售后服务网络。1996年以来，唐山松下的销售额一直位居中国电焊机行业首位，并被日本松下公司评价为“松下在华的最佳合资企业”。唐山松下在电焊机行业的位置是中国第一，亚洲第三、世界前十。作为目前国内最大的焊接设备制造企业，唐山松下以领先的科技和优良的产品品质赢得了用户的广泛赞誉，Panasonic电焊机成为行业界最受欢迎的品牌。', 4, 0, '电气机械/电力设备', 'https://www.zhaopin.com/jobdetail/CC120963930J40809676303.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400008, 200008, '安科瑞', '安科瑞电气股份有限公司[股票代码:300286.SZ]是一家为智能电网用户端提供智能电力监控、电能管理、电气安全等系统性解决方案的国内少数几家领先企业之一。公司自2003年6月成立以来，专注于用户端智能电力仪表的研发、生产和销售，产品线涵盖了智能电网用户端的低压电力信号采集、测量、计量、监控、保护及系统集成，主要有网络电力仪表、智能马达控制器、导轨式安装电能表、电量传感器、光伏汇流箱、有源滤波器、医疗洁净电源柜等产品以及智能电力监控与电能管理、建筑能耗分析管理、电气火灾监控、数据中心用电监控、光伏电站监控、ZigBee（物联网）无线电能管理等系统方案。是上海市高新技术企业、小巨人企业、明星软件企业、专利示范企业，是上海市首批智能电网产业重点企业之一。', 5, 6, '仪器仪表制造', 'https://www.zhaopin.com/jobdetail/CC134247150J40728461507.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400009, 200009, '济南北海软件工程有限公司', '公司简介公司成立于2010年10月，位于中国（山东）自由贸易试验区济南片区（高新区软件园周边）。济南北海拥有一支技术出众、熟知中日两国软件开发模式的工程师团队。自成立以来，济南北海已经承担了日本以及多家国内企业的各种类型的人才派遣、项目外包及委托开发项目。尤其擅长WEB开发WINDOWS应用系统开发与生产管理类系统开发。以高度的灵活性和挑战精神在最短的时间内应对客户的需求，努力为客户提供最合适的人才服务和完善的技术服务，以“专业、迅速、守信”为宗旨，一步一个脚印发展成为济南外包行业内颇具影响力的企业。我们的团队我们是一支专业的团队。十年磨一剑，一步一个脚印。我们是一支年轻的团队。我们是一支团结的团队。我们坚信，只有团结，才能战无不胜攻无不克。我们是一支有梦想的团队。我们来自五湖四海，因为一个共同的梦想:做一家真正优质的IT行业服务提供商，为客户提供最专业的技术和人力服务。', 2, 0, '计算机软件', 'https://www.zhaopin.com/jobdetail/CC120776610J40817210808.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400010, 200010, '源创客成都科技有限公司', '', 2, 0, '计算机软件', 'https://www.zhaopin.com/jobdetail/CC640419780J40814291403.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400011, 200011, '外企德科数字技术有限公司', '外企德科数字技术有限公司是一家2023年新成立的中外合资企业。成立于2023年11月24日，公司定位：专注于为信息技术企业提供人才及数字技术外包解决方案的中外合资企业。它是由中国人力资源服务行业的FESCO（北京国际人力资本集团）与全球人力资源服务领导者The Adecco Group（德科集团）合资成立的。公司主要提供网络技术服务、软件外包服务、计算机系统服务、技术进出口、软件开发等信息技术相关服务。专注于为信息技术企业提供信息技术类人才及数字技术外包解决方案。', 7, 0, '专业技术服务', 'https://www.zhaopin.com/jobdetail/CCL1480117890J40768591805.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400012, 200012, '数码大方', '数码大方（CAXA）是中国领先的工业软件和工业互联网公司。公司是“智能化协同制造技术及应用”国家工程实验室承建单位，也是国家级高新技术企业、中关村高新技术企业、中关村示范区信用五星级企业、北京市高新技术成果转化示范企业、北京市专利示范单位、工信部首批智能制造系统供应商。数码大方始终坚持技术创新，完全自主研发数字化设计（CAD）、产品全生命周期管理（PLM）、数字化制造（MES）软件，是中国最早从事此领域的软件公司，研发团队拥有多年专业经验积累，具有国际领先技术水平，在北京、南京和美国亚特兰大设有三个研发中心，目前已拥有330余项商标、专利、专利申请及著作权。公司是国家智能制造标准化总体组成员单位、大数据标准工作组全权成员单位、中国信息技术标准化技术委员会委员、北京标准化协会单位会员，牵头或参与国家智能制造标准、工业云、工业大数据、增材制造等标准体系的建设。数码大方致力成为世界一流的工业软件和工业互联网公司！http://www.caxa.com/', 4, 0, '计算机软件', 'https://www.zhaopin.com/jobdetail/CC391669320J40734517805.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400013, 200013, '天阳科技', '天阳科技(股票代码：300872)，是全球金融创新服务的重要贡献者，持续赋能中国金融行业数字化转型，为客户提供咨询、金融科技产品、金融IT服务、云计算及运营服务。公司成立于2003年，服务超过300家金融行业客户，覆盖中央银行、政策性银行、国有银行、股份制银行、地方性商业银行、非银行金融机构等，员工人数近7000人，成为激活金融领域创新活力、推动金融科技迈入世界领先水平的重要力量。作为金融行业客户可信赖的合作伙伴，天阳科技凭借丰富的行业经验和端到端的专业服务，在信创、数字化金融、信贷、交易银行、信用卡、零售、营销、风险管理、征信监管等众多领域具备核心竞争力。据赛迪和IDC报告显示，近年来公司在中国银行业IT解决方案市场排名强势崛起，2019年收入及市场占有率综合排名分别位列第四位和第五位，并保持高速增长。同时，前瞻商业和科技趋势，入选2021年度未来银行科技服务商TOP100。天阳科技始终聚焦金融科技领域，加大自主创新力度，在超过100个城市建立本地化、专业化的研发和服务团队，拥有CMMI5级认证、软件测试成熟度模型集成（TMMi）3级认证、ISO9001质量管理体系认证、ISO20000信息技术服务管理体系认证、IS027001信息安全管理体系认证。通过部署人工智能、云计算、大数据、移动互联网、分布式计算和区块链等先进金融科技，公司致力于构建安全可控、普惠民生、开放共赢格局，在关键技术领域服务现代化金融发展大局，更好地为各利益相关方创造更大价值，为大中企业、小微企业以及每个个体提供优质金融服务。', 5, 6, '计算机软件', 'https://www.zhaopin.com/jobdetail/CC120408370J40294365608.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400014, 200014, '中国科学院微电子研究所', '中国科学院微电子研究所自诞生起就是中国微电子技术创新的引领者和产业发展的推动者。经过六十多年的发展，中国科学院微电子研究所已经成为国内微电子领域学科方向布局最完整的综合研究与开发机构，是国家科技重大专项集成电路装备及工艺前瞻性研发牵头组织单位，是中国科学院大学微电子学院（国家示范性微电子学院）的依托单位，是中国科学院集成电路创新研究院的筹建依托单位。现拥有2个基础研究类中国科学院重点实验室（微电子器件与集成技术重点实验室、硅器件技术重点实验室），5个行业服务类研发中心（EDA中心、集成电路先导技术研发中心、系统封装与集成研发中心、中科新芯三维存储器研发中心、光刻技术总体部），7个行业应用类研发中心（通信与信息工程研发中心、新能源汽车电子研发中心、健康电子研发中心、智能感知研发中心、智能制造电子研发中心、智能电子系统研发中心、电磁信息智能应用研究中心），4个核心产品类研发中心（硅器件与集成研发中心、高频高压器件与集成研发中心、微电子仪器设备研发中心、光电技术研发中心）。截至目前，微电子所共有在职职工一千余人，包括中国科学院院士2人、发展中国家科学院院士1人、国家杰出青年科学基金获得者4人。研究员及正高级工程技术人员150人、副研究员及高级工程技术人员343人。微电子所坚持开放办所理念，坚持“企业为主体，市场为导向，产学研用结合”的对外合作思路，与北京大学、清华大学、复旦大学等高校和武汉新芯、上海华力、华润微电子、北方微电子等企业结为战略合作伙伴，在北京、江苏、湖北、四川、广东、湖南等省市开展科技成果转移转化，在我国微电子领域拥有广泛的影响，为支撑我国微电子产业核心竞争力发挥了不可替代的重要作用。联系方式：hr@ime.ac.cn(只接受问题咨询)官网：http://www.ime.cas.cn/地址：北京市朝阳区北土城西路3号', 5, 0, '电子/半导体/集成电路', 'https://www.zhaopin.com/jobdetail/CC000551140J40731705207.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400015, 200015, '青岛瑞晟元人力资源有限公司', '', 1, 0, '人力资源服务', 'https://www.zhaopin.com/jobdetail/CCL1431271280J40777137407.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400016, 200016, '联合汽车电子有限公司（UAES）', '联合汽车电子有限公司（UAES）成立于1995年12月，它是由全球500强企业之一的汽车零部件制造商德国博世（BOSCH）和中联汽车电子有限公司合资的企业，是目前国内最大的生产汽车零部件的合资企业之一。它引进世界先进技术、具有专业生产和销售汽油发动机管理系统、汽车车身电子和传动控制系统及其零部件的能力，是一个集产品生产、技术研发、市场销售及售后服务为一体的高新技术企业。联合汽车电子有限公司总部位于上海浦东新区，并在无锡、西安、重庆、芜湖、柳州分别有分厂和技术(研发)中心。凭借技术和市场的优势以及专业化的管理，联合汽车电子有限公司取得了良好的经营业绩。公司2016年销售额突破200亿人民币，占据着中国电喷市场的主导地位。', 5, 0, '金属制品业', 'https://www.zhaopin.com/jobdetail/CC000260640J40852151604.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400017, 200017, '米斯特奥福(大连)咨询服务有限公司', '米斯特奥福（大连）咨询服务有限公司是一家专注于IT行业猎聘服务的人力资源服务机构，尤其擅长对日软件，车载软件，电商软件，ERP软件等开发及管理人才招聘，目前已成功为数十家知名IT企业招聘数百名IT研发类人才，目前是多家知名IT企业的核心猎头服务商。顾问团队均为工作经验5-10年的资深猎头顾问，招聘经验丰富，业绩卓越，善于精准匹配企业的人才需求和候选人的求职意向，达到双赢的效果。我们的人才储备丰富，分布在辽宁，北京，上海，广州，深圳，浙江，江苏，福建，日本，美国，韩国，新加坡等多个省市和国家。', 1, 0, '人力资源服务', 'https://www.zhaopin.com/jobdetail/CC323581030J40774649613.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400018, 200018, '河北御棠源生态农业有限公司', '', 2, 0, '文化艺术/娱乐', 'https://www.zhaopin.com/jobdetail/CCL1423246960J40491730414.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400019, 200019, '山东中天宇信信息技术有限公司', '山东中天宇信信息技术有限公司是一家拥有互联网创新思维和现代化管理理念及管理制度的高科技企业，公司以实施“智慧农业云服务平台”为主要经营内容。总体经营发展思路是以“农业大数据”为驱动，以“农业物联网技术”、“AI人工智能”、“区块链技术”、“智能深度学习技术”等为路线，实现涉农企业智慧化、精准化种田。基于AI人工智能和深度学习技术打造国内第一款农业语音交互机器人－农小嗨，帮助农业企业实现语音自动化控制、农业知识问答、种植标准、市场行情等相关的查询服务，为国内农业企业智慧化、精准化种田提供帮助。公司先后通过双软和国家级科技型中小企业的认定，拥有30余项自主知识产权的软件著作权证书；与阿里云农业大脑、安徽省农业大学、山东农业大学、安徽省农产品质量安全促进会、中国诚信建设研究中心等多个单位建立合作，整合多方资源及专业领域的技术共同打造国内一流的智慧农业解决方案。推动食品安全，增强政府智慧监管，为广大农业基地、农业服务机构及监管部门提供更智能、更先进的技术服务。', 2, 0, '计算机软件', 'https://www.zhaopin.com/jobdetail/CC852890130J40460862510.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00'),
(400020, 200020, '宜宾丰川动力科技有限公司', '宜宾丰川动力科技有限公司宜宾丰川动力科技有限公司是一家研发和生产电动汽车多档变速器的高新技术企业。公司实行“功以才成，业由才广”的人才战略，组建了30人规模的研发团队，从清华大学、同济大学、美国伊利诺伊大学、法国贡比涅技术大学等国内外知名高校引进了多名博士、硕士。研发团队经过十余年技术攻关，开发了无离合器、无同步器的电驱动机械变速器，并发明了“无冲击换档”控制技术，彻底消除了换档过程的冲击，将动力中断时间缩短到了0.2秒内，突破了制约多档变速器在电动汽车中大规模推广应用的技术瓶颈。公司已开发出适用于2-4吨电动物流车的二档系统和适用于4-8吨电动物流车的四档系统，并应用于城市物流车中。', 2, 0, '汽车研发/制造', 'https://www.zhaopin.com/jobdetail/CC640599680J40206154607.htm?refcode=4019&srccode=401901&preactionid=a7c1140f-c46c-45e5-b867-ab342d8bdc77', NULL, '五险一金,周末双休,绩效奖金', 1, '2026-06-04 16:00:00', '2026-06-04 16:00:00', NULL, NULL, 'approved', '2026-06-04 16:00:00')
